package com.example.bookstore.controller;
import com.example.bookstore.dto.*; import com.example.bookstore.service.CategoryService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/categories") public class CategoryController { private final CategoryService service; public CategoryController(CategoryService service){this.service=service;} @PostMapping ResponseEntity<CategoryResponse> create(@Valid @RequestBody CategoryRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @GetMapping List<CategoryResponse> all(){return service.findAll();} @GetMapping("/{id}") CategoryResponse one(@PathVariable Long id){return CategoryResponse.from(service.get(id));} @PutMapping("/{id}") CategoryResponse update(@PathVariable Long id,@Valid @RequestBody CategoryRequest r){return service.update(id,r);} @DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();} }
